+// deno-lint-ignore-file no-explicit-any
+import { join, resolve } from "@std/path";
+import { ConfigParseError } from "./errors.ts";
+import type { ConfigOptions } from "./types.ts";
+
+export interface LoadedConfig {
+  path?: string;
+  values: Record<string, unknown>;
+}
+
+export async function loadConfig(options: ConfigOptions): Promise<LoadedConfig> {
+  const paths = options.searchPaths ?? [currentDirectory()];
+  const formats = options.formats ?? [".json", ".rc"];
+  const matches: Array<{ path: string; values: Record<string, unknown> }> = [];
+
+  for (const searchPath of paths) {
+    const match = await findConfig(searchPath, options.name, formats, options.parser);
+    if (match) {
+      matches.push(match);
+      if (!options.mergeConfigs) break;
+    }
+  }
+
+  if (!matches.length) return { values: {} };
+
+  // Earlier paths have higher priority.
+  const values = matches.reduceRight<Record<string, unknown>>(
+    (merged, match) => ({ ...merged, ...match.values }),
+    {},
+  );
+  return { path: matches[0].path, values };
+}
+
+async function findConfig(
+  searchPath: string,
+  name: string,
+  formats: string[],
+  parser?: ConfigOptions["parser"],
+): Promise<{ path: string; values: Record<string, unknown> } | undefined> {
+  for (const format of formats) {
+    const path = resolve(join(searchPath, format === ".rc" ? `.${name}rc` : `${name}${format}`));
+    let content: string;
+    try {
+      content = await readTextFile(path);
+    } catch (error) {
+      if (isNotFound(error)) continue;
+      throw error;
+    }
+    try {
+      const values = parser ? parser(content) : format === ".rc" ? parseRc(content) : JSON.parse(content);
+      if (!isPlainObject(values)) throw new TypeError("Config root must be a plain object.");
+      return { path, values: flattenValues(values) };
+    } catch (error) {
+      throw new ConfigParseError(path, error);
+    }
+  }
+}
+
+function currentDirectory(): string {
+  const deno = (globalThis as any).Deno;
+  return deno ? deno.cwd() : process.cwd();
+}
+
+async function readTextFile(path: string): Promise<string> {
+  const deno = (globalThis as any).Deno;
+  if (deno) return await deno.readTextFile(path);
+  const { readFile } = await import("node:fs/promises");
+  return await readFile(path, "utf8");
+}
+
+function isNotFound(error: unknown): boolean {
+  return !!error && typeof error === "object" &&
+    ((error as { name?: string }).name === "NotFound" ||
+      (error as { code?: string }).code === "ENOENT");
+}
+
+function parseRc(content: string): Record<string, unknown> {
+  const values: Record<string, unknown> = {};
+  for (const line of content.split(/\\r?\
/)) {
+    const trimmed = line.trim();
+    if (!trimmed || trimmed.startsWith("#")) continue;
+    const separator = line.indexOf("=");
+    if (separator === -1) throw new TypeError(`Invalid RC entry "${line}".`);
+    const key = line.slice(0, separator).trim();
+    let value = line.slice(separator + 1).trim();
+    if (!key) throw new TypeError("RC keys cannot be empty.");
+    if (value.startsWith('"') && value.endsWith('"') && value.length >= 2) {
+      value = value.slice(1, -1);
+    }
+    values[key] = coerceRcValue(value);
+  }
+  return values;
+}
+
+function coerceRcValue(value: string): string | boolean | number {
+  if (value === "true") return true;
+  if (value === "false") return false;
+  if (/^-?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][+-]?\\d+)?$/.test(value)) return Number(value);
+  return value;
+}
+
+function isPlainObject(value: unknown): value is Record<string, unknown> {
+  return !!value && typeof value === "object" && !Array.isArray(value) &&
+    (Object.getPrototypeOf(value) === Object.prototype || Object.getPrototypeOf(value) === null);
+}
+
+function flattenValues(values: Record<string, unknown>, prefix = ""): Record<string, unknown> {
+  return Object.entries(values).reduce<Record<string, unknown>>((result, [key, value]) => {
+    const name = prefix ? `${prefix}.${camelCase(key)}` : camelCase(key);
+    if (isPlainObject(value)) Object.assign(result, flattenValues(value, name));
+    else result[name] = value;
+    return result;
+  }, {});
+}
+
+function camelCase(value: string): string {
+  return value.replace(/-([a-zA-Z0-9])/g, (_, char) => char.toUpperCase());
+}
